function check(input, actual, expected) {
  const [s] = input;
  if (!Array.isArray(actual) || actual.length === 0 || typeof actual[0] !== 'string') return false;
  // Rebuild the tree from its level-order list.
  const root = { val: actual[0], left: null, right: null };
  const queue = [root];
  let i = 1;
  for (let q = 0; q < queue.length && i < actual.length; q++) {
    for (const side of ['left', 'right']) {
      if (i < actual.length && actual[i] !== null) {
        if (typeof actual[i] !== 'string') return false;
        queue[q][side] = { val: actual[i], left: null, right: null };
        queue.push(queue[q][side]);
      }
      i++;
    }
  }
  if (i < actual.length) return false;
  // Leaves are digits; every operator node has two children.
  for (const node of queue) {
    const leaf = !node.left && !node.right;
    if (/^[0-9]$/.test(node.val) ? !leaf : !/^[-+*/]$/.test(node.val) || !node.left || !node.right) return false;
  }
  // The in-order walk must spell s without its parentheses.
  const order = [];
  const walk = node => { if (node) { walk(node.left); order.push(node); walk(node.right); } };
  walk(root);
  if (order.map(node => node.val).join('') !== s.replace(/[()]/g, '')) return false;
  // Compare the tree with s as formulas: give the operands pseudo-random values and evaluate both modulo a prime.
  const P = 67108859;
  const inverse = a => { let result = 1, base = a, e = P - 2; while (e > 0) { if (e & 1) result = result * base % P; base = base * base % P; e = Math.floor(e / 2); } return result; };
  const apply = (op, a, b) => {
    if (Number.isNaN(a) || Number.isNaN(b)) return NaN;
    if (op === '+') return (a + b) % P;
    if (op === '-') return (a - b + P) % P;
    if (op === '*') return a * b % P;
    return b === 0 ? NaN : a * inverse(b) % P;
  };
  const leaves = order.filter(node => !node.left);
  let compared = 0;
  for (let trial = 1; trial <= 4; trial++) {
    let seed = trial * 7919;
    const values = leaves.map(() => { seed = (seed * 48271) % 2147483647; return seed % P; });
    const index = new Map(leaves.map((node, k) => [node, k]));
    const evalTree = node => node.left ? apply(node.val, evalTree(node.left), evalTree(node.right)) : values[index.get(node)];
    // Evaluate s itself with the usual precedence, operands numbered left to right.
    let pos = 0;
    let operand = 0;
    const factor = () => {
      if (s[pos] === '(') { pos++; const value = sum(); pos++; return value; }
      pos++;
      return values[operand++];
    };
    const product = () => { let value = factor(); while (s[pos] === '*' || s[pos] === '/') { const op = s[pos++]; value = apply(op, value, factor()); } return value; };
    const sum = () => { let value = product(); while (s[pos] === '+' || s[pos] === '-') { const op = s[pos++]; value = apply(op, value, product()); } return value; };
    const want = sum();
    const got = evalTree(root);
    if (Number.isNaN(want) || Number.isNaN(got)) continue;
    if (want !== got) return false;
    compared++;
  }
  return compared >= 2;
}

validator:
function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 's must have 1 to 100 characters.';
  if (!/^[0-9+\-*/()]+$/.test(s)) return 's may contain only digits, + - * / and parentheses.';
  // A small recursive-descent parse: expression = term (operator term)*, term = digit or ( expression ).
  let pos = 0;
  const term = () => {
    if (s[pos] === '(') { pos++; if (!expression() || s[pos] !== ')') return false; pos++; return true; }
    if (pos < s.length && s[pos] >= '0' && s[pos] <= '9') { pos++; return true; }
    return false;
  };
  const expression = () => {
    if (!term()) return false;
    while (pos < s.length && '+-*/'.includes(s[pos])) { pos++; if (!term()) return false; }
    return true;
  };
  if (!expression() || pos !== s.length) return 's must be a well-formed expression of single digits, operators and balanced, non-empty parentheses.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [s] = input;
  const root = solve(s);
  if (!root || typeof root !== 'object') throw new Error('Return the root node of the expression tree.');
  // Show values as the one-character strings the tree should hold.
  return kit.fromTree(root).map(value => (value === null ? null : String(value)));
}

