function expTree(s) {
  const rank = { '(': 0, '+': 1, '-': 1, '*': 2, '/': 2 };
  const nodes = [];
  const ops = [];
  const combine = () => {
    const right = nodes.pop();
    const left = nodes.pop();
    nodes.push(new TreeNode(ops.pop(), left, right));
  };

  for (const ch of s) {
    if (ch >= '0' && ch <= '9') {
      nodes.push(new TreeNode(ch));
    } else if (ch === '(') {
      ops.push(ch);
    } else if (ch === ')') {
      while (ops[ops.length - 1] !== '(') {
        combine();
      }
      ops.pop();
    } else {
      while (ops.length > 0 && rank[ops[ops.length - 1]] >= rank[ch]) {
        combine();
      }
      ops.push(ch);
    }
  }
  while (ops.length > 0) {
    combine();
  }
  return nodes[0];
}

brute:
function expTree(s) {
  // Split recursively at the operator applied last: the rightmost + or - outside all parentheses,
  // or failing that the rightmost * or /; strip parentheses that wrap the whole piece.
  const build = (from, to) => {
    while (s[from] === '(') {
      let depth = 0;
      let closes = -1;
      for (let k = from; k < to; k++) {
        if (s[k] === '(') depth++;
        if (s[k] === ')') depth--;
        if (depth === 0) { closes = k; break; }
      }
      if (closes !== to - 1) break;
      from++;
      to--;
    }
    if (to - from === 1) return new TreeNode(s[from]);
    for (const group of ['+-', '*/']) {
      let depth = 0;
      for (let k = to - 1; k >= from; k--) {
        if (s[k] === ')') depth++;
        else if (s[k] === '(') depth--;
        else if (depth === 0 && group.includes(s[k])) return new TreeNode(s[k], build(from, k), build(k + 1, to));
      }
    }
    return null;
  };
  return build(0, s.length);
}

generator:
function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const pool = ['+-*/', '-', '/', '-*', '+/', '+-*/'][pick(6)];
  const expression = depth => {
    const terms = 1 + pick(large ? 6 : 3);
    let text = '';
    for (let t = 0; t < terms; t++) {
      if (t > 0) text += pool[pick(pool.length)];
      text += depth < (large ? 4 : 2) && rand() < 0.3 ? `(${expression(depth + 1)})` : String(pick(10));
    }
    return text;
  };
  for (;;) {
    const s = expression(0);
    if (large ? s.length >= 70 && s.length <= 100 : s.length <= 15) return [s];
  }
}
